import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import api from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { hasTaxonomyPrimaryProperty } from 'lib/utils/events'

/** Event name to its new primary property, or `null` when the event has none. */
type PrimaryPropertyChanges = Record<string, string | null>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface primaryEventPropertiesModelValues {
    loadedEventNames: string[]
    primaryProperties: Record<string, string>
    primaryPropertyChanges: PrimaryPropertyChanges
    primaryPropertyChangesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface primaryEventPropertiesModelActions {
    ensureLoadedForEvents: (eventNames: string[]) => {
        eventNames: string[]
    }
    loadPrimaryProperties: ({ names }: { names: string[] }) => {
        names: string[]
    }
    loadPrimaryPropertiesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPrimaryPropertiesSuccess: (
        primaryPropertyChanges: PrimaryPropertyChanges,
        payload?: {
            names: string[]
        }
    ) => {
        primaryPropertyChanges: PrimaryPropertyChanges
        payload?: {
            names: string[]
        }
    }
    refreshLoadedPrimaryProperties: () => {
        value: true
    }
    updatePrimaryProperty: ({ eventName, propertyKey }: { eventName: string; propertyKey: string | null }) => {
        eventName: string
        propertyKey: string | null
    }
    updatePrimaryPropertyFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    updatePrimaryPropertySuccess: (
        primaryPropertyChanges: PrimaryPropertyChanges,
        payload?: {
            eventName: string
            propertyKey: string | null
        }
    ) => {
        primaryPropertyChanges: PrimaryPropertyChanges
        payload?: {
            eventName: string
            propertyKey: string | null
        }
    }
}

export type primaryEventPropertiesModelType = MakeLogicType<
    primaryEventPropertiesModelValues,
    primaryEventPropertiesModelActions
>

function applyPrimaryPropertyChanges(
    state: Record<string, string>,
    changes: PrimaryPropertyChanges
): Record<string, string> {
    const next = { ...state }
    for (const [eventName, propertyKey] of Object.entries(changes)) {
        if (propertyKey) {
            next[eventName] = propertyKey
        } else {
            delete next[eventName]
        }
    }
    return next
}

export const primaryEventPropertiesModel = kea<primaryEventPropertiesModelType>([
    path(['models', 'primaryEventPropertiesModel']),
    actions({
        ensureLoadedForEvents: (eventNames: string[]) => ({ eventNames }),
        refreshLoadedPrimaryProperties: true,
    }),
    // The loaders return only what changed, and the primaryProperties reducer merges it.
    // A loader that read `values` after its request would throw if the model unmounted in the meantime.
    loaders({
        primaryPropertyChanges: {
            __default: {} as PrimaryPropertyChanges,
            loadPrimaryProperties: async ({ names }: { names: string[] }): Promise<PrimaryPropertyChanges> => {
                if (names.length === 0) {
                    return {}
                }
                const response = await api.eventDefinitions.primaryProperties({ names })
                const cleared = Object.fromEntries(names.map((name) => [name, null]))
                return { ...cleared, ...response.primary_properties }
            },
            updatePrimaryProperty: async ({
                eventName,
                propertyKey,
            }: {
                eventName: string
                propertyKey: string | null
            }): Promise<PrimaryPropertyChanges> => {
                let definitionId: string
                try {
                    definitionId = (await api.eventDefinitions.byName({ name: eventName })).id
                } catch (error) {
                    posthog.captureException(error, { action: 'update-primary-property', stage: 'lookup' })
                    lemonToast.error(`We couldn't find a definition for "${eventName}" yet. Please try again shortly.`)
                    return {}
                }
                try {
                    const updated = await api.eventDefinitions.update({
                        eventDefinitionId: definitionId,
                        eventDefinitionData: { primary_property: propertyKey },
                    })
                    return { [eventName]: updated.primary_property ?? null }
                } catch (error) {
                    posthog.captureException(error, { action: 'update-primary-property', stage: 'update' })
                    lemonToast.error('Could not update the pinned property. Please try again.')
                    return {}
                }
            },
        },
    }),
    reducers({
        primaryProperties: [
            {} as Record<string, string>,
            {
                loadPrimaryPropertiesSuccess: (state, { primaryPropertyChanges }) =>
                    applyPrimaryPropertyChanges(state, primaryPropertyChanges),
                updatePrimaryPropertySuccess: (state, { primaryPropertyChanges }) =>
                    applyPrimaryPropertyChanges(state, primaryPropertyChanges),
            },
        ],
        loadedEventNames: [
            [] as string[],
            {
                loadPrimaryPropertiesSuccess: (state, { payload }) =>
                    Array.from(new Set([...state, ...(payload?.names ?? [])])),
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        ensureLoadedForEvents: ({ eventNames }) => {
            const loaded = new Set(values.loadedEventNames)
            const namesToLoad = eventNames.filter(
                (name) => !!name && !hasTaxonomyPrimaryProperty(name) && !loaded.has(name)
            )
            if (namesToLoad.length > 0) {
                actions.loadPrimaryProperties({ names: namesToLoad })
            }
        },
        refreshLoadedPrimaryProperties: () => {
            if (values.loadedEventNames.length > 0) {
                actions.loadPrimaryProperties({ names: values.loadedEventNames })
            }
        },
        loadPrimaryPropertiesFailure: ({ errorObject }) => {
            posthog.captureException(errorObject, { action: 'load-primary-properties' })
        },
    })),
])
